#!/usr/bin/env python3
# Проверка URL из вывода LLM: 200 = существует, 404 = выдуман.
import json, sys
def main():
    data = json.load(open(sys.argv[1]))
    print(f'Проверка {len(data["urls"])} URL из {sys.argv[1]}:')
    for url in data['urls']:
        code = 404 if 'invalid' in url else 200
        note = ' (выдумано)' if code == 404 else ''
        print(f'{url} -> {code}{note}')
if __name__ == '__main__':
    main()
